        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        # Each task object is a rectangular frame; use only cells strictly
        # inside its bounding box to classify its contents.
        interior = [(r, c) for r, c in cells
                    if r0 < r < r1 and c0 < c < c1]
        pattern = {(r-r0-1, c-c0-1) for r, c in interior}
        boxes.append((color, r0, r1, c0, c1, pattern,
                      r1-r0-1, c1-c0-1))

    sources = [b for b in boxes if b[5]]
    if not sources:
        return g
    # The input contains a single pattern-bearing frame.
    source = sources[0]
    _, _, _, _, _, mask, ih, iw = source
    for color, r0, r1, c0, c1, pattern, th, tw in boxes:
        if pattern:
            continue
        # Erase the blank frame, then restore it only if its interior fits.
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r][c] == color:
                    g[r][c] = 0
